function normalizeUiLanguage(value) {
  const lang = String(value || "auto").trim().toLowerCase().replace(/_/g, "-");
  if (lang === "auto" || lang === "en") return lang;
  return /^[a-z]{2,3}(?:-[a-z0-9]{2,8})*$/.test(lang) ? lang : "auto";
}

function parseUiLocaleFileName(filePath) {
  const fileName = String(filePath || "").split("/").pop() || "";
  const stem = fileName.replace(/\.json$/i, "");
  const versioned = stem.match(/^([a-z]{2,3}(?:-[a-z0-9]{2,8})*)_(\d+\.\d+\.\d+(?:[_-]?[a-z]+\d*)?)$/i);
  if (versioned) {
    return {
      code: normalizeUiLanguage(versioned[1]),
      updatedForPluginVersion: versioned[2],
      fileName,
    };
  }
  return {
    code: normalizeUiLanguage(stem),
    updatedForPluginVersion: "",
    fileName,
  };
}

function parseComparablePluginVersion(value) {
  const raw = String(value || "").trim();
  if (!raw) return null;
  const normalized = raw.replace(/_/g, "-");
  const match = normalized.match(/^(\d+)\.(\d+)\.(\d+)(?:-([a-z]+)(\d*)?)?$/i);
  if (!match) return null;
  const stageName = String(match[4] || "release").toLowerCase();
  const stageRanks = { dev: 0, alpha: 1, a: 1, beta: 2, b: 2, rc: 3, release: 4 };
  const stageRank = Object.prototype.hasOwnProperty.call(stageRanks, stageName) ? stageRanks[stageName] : 0;
  return {
    major: Number(match[1]),
    minor: Number(match[2]),
    patch: Number(match[3]),
    stageRank,
    stageName,
    stageNumber: Number(match[5] || 0),
    raw,
  };
}

function comparePluginVersions(leftValue, rightValue) {
  const left = parseComparablePluginVersion(leftValue);
  const right = parseComparablePluginVersion(rightValue);
  if (!left || !right) return null;
  for (const key of ["major", "minor", "patch", "stageRank", "stageNumber"]) {
    if (left[key] < right[key]) return -1;
    if (left[key] > right[key]) return 1;
  }
  return 0;
}

function localePackVersionRelation(packVersion, pluginVersion) {
  if (!packVersion) return "unversioned";
  const compared = comparePluginVersions(packVersion, pluginVersion);
  if (compared === null) return "unknown";
  if (compared < 0) return "older";
  if (compared > 0) return "newer";
  return "current";
}

function chooseUiLocaleCandidate(candidates, pluginVersion) {
  if (!Array.isArray(candidates) || !candidates.length) return null;
  const rank = (candidate) => {
    const relation = localePackVersionRelation(candidate.updatedForPluginVersion, pluginVersion);
    if (relation === "current") return 4;
    if (relation === "older") return 3;
    if (relation === "unversioned") return 2;
    if (relation === "newer") return 1;
    return 0;
  };
  return candidates.slice().sort((left, right) => {
    const rankDelta = rank(right) - rank(left);
    if (rankDelta) return rankDelta;

    const leftVersion = left.updatedForPluginVersion || "";
    const rightVersion = right.updatedForPluginVersion || "";
    const relation = localePackVersionRelation(leftVersion, pluginVersion);
    const compared = leftVersion && rightVersion ? comparePluginVersions(leftVersion, rightVersion) : null;
    if (compared !== null && compared !== 0) {
      if (relation === "newer") return compared;
      return -compared;
    }

    const directoryDelta = Number(right.directoryIndex || 0) - Number(left.directoryIndex || 0);
    if (directoryDelta) return directoryDelta;
    return String(left.filePath || "").localeCompare(String(right.filePath || ""));
  })[0];
}

function languageFromLocale(locale) {
  const value = String(locale || "").trim().toLowerCase().replace(/_/g, "-");
  if (!value) return "en";

  const candidates = [normalizeUiLanguage(value)];
  const parts = value.split("-");
  if (parts[0] === "zh") {
    const traditional = parts.some((part) => part === "tw" || part === "hk" || part === "mo" || part === "hant");
    candidates.push(traditional ? "zh-tw" : "zh-cn");
  }
  candidates.push(normalizeUiLanguage(parts[0]));

  for (const candidate of candidates) {
    if (candidate !== "auto" && UI_TRANSLATIONS[candidate]) return candidate;
  }
  return "en";
}

function resolveUiLanguage(settingValue, localeValue) {
  const configured = normalizeUiLanguage(settingValue);
  return configured === "auto" ? languageFromLocale(localeValue) : configured;
}

function translateUiText(language, en) {
  const lang = normalizeUiLanguage(language);
  const source = String(en || "");
  if (lang === "en" || lang === "auto") return source;

  const dictionary = UI_TRANSLATIONS[lang] || {};
  if (Object.prototype.hasOwnProperty.call(dictionary, source)) {
    return String(dictionary[source]);
  }

  for (const item of UI_TRANSLATION_PATTERNS[lang] || []) {
    if (!item || !item.pattern || typeof item.replace !== "string") continue;
    try {
      const regex = new RegExp(item.pattern, item.flags || "");
      if (regex.test(source)) return source.replace(regex, item.replace);
    } catch (_) {}
  }

  return source;
}

function isNtfyInboxAttachmentPath(value) {
  const normalized = String(value || "").replace(/\\/g, "/").replace(/^\/+|\/+$/g, "");
  return normalized === ".trash/ntfy-inbox" || normalized.startsWith(".trash/ntfy-inbox/");
}

function ntfyBytesToBase64Url(value) {
  const bytes = value instanceof Uint8Array ? value : new Uint8Array(value || []);
  if (typeof Buffer !== "undefined") return Buffer.from(bytes).toString("base64url");
  let binary = "";
  for (let index = 0; index < bytes.length; index += 32768) {
    binary += String.fromCharCode(...bytes.subarray(index, Math.min(bytes.length, index + 32768)));
  }
  return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/g, "");
}

async function hashNtfyBytes(value) {
  const bytes = value instanceof Uint8Array ? value : new Uint8Array(value || []);
  if (typeof crypto !== "undefined" && crypto.subtle?.digest) {
    const digest = await crypto.subtle.digest("SHA-256", bytes);
    return ntfyBytesToBase64Url(new Uint8Array(digest));
  }
  if (Platform.isDesktopApp && typeof require === "function") return require("node:crypto").createHash("sha256").update(Buffer.from(bytes)).digest("base64url");
  throw new Error("SHA-256 is unavailable");
}

async function ensureNtfyFolder(adapter, folderPath) {
  const rawFolder = String(folderPath || "").replace(/\\/g, "/").replace(/^\/+|\/+$/g, "");
  const folder = rawFolder === ".trash/ntfy-inbox" || /^\.trash\/ntfy-inbox\/[A-Za-z0-9_-]{16,96}$/.test(rawFolder)
    ? rawFolder
    : normalizePath(rawFolder).replace(/^\/+|\/+$/g, "");
  const parts = folder.split("/").filter(Boolean);
  let current = "";
  for (const part of parts) {
    current = current ? `${current}/${part}` : part;
    const stat = await adapter.stat(current);
    if (stat?.type === "file") throw new Error(`Path is a file: ${current}`);
    if (!stat) await adapter.mkdir(current);
  }
}

function safeNtfyAttachmentName(value) {
  const name = String(value || "attachment.bin")
    .trim()
    .replace(/[\\/:*?"<>|\u0000-\u001f]/g, "_")
    .replace(/^\.+|\.+$/g, "")
    .replace(/\s+/g, " ")
    .slice(0, 180);
  return name && name !== "." && name !== ".." ? name : "attachment.bin";
}

