        new Setting(containerEl)
          .setName(this.uiText("Language files"))
          .setDesc(`${this.uiText("Reload external locale JSON files from the locales folder.")} ${this.uiText("Versioned file names are supported; older packs remain usable and missing strings fall back to English.")}`)
